#include <SPI.h>
#include <Adafruit_GFX.h>

// ---------- Команды ILI9341 / ILI9342C ----------
#define SWRESET  0x01
#define RDID     0x04
#define SLPOUT   0x11
#define INVOFF   0x20
#define INVON    0x21
#define DISPON   0x29
#define CASET    0x2A
#define PASET    0x2B
#define RAMWR    0x2C
#define RAMRD    0x2E
#define MADCTL   0x36
#define COLMOD   0x3A

// ---------- Свой программный (bit-bang) SPI-драйвер ----------
class ILI934x : public Adafruit_GFX {
public:
  int8_t _sclk, _mosi, _miso, _cs, _dc, _rst, _bl;
  bool _inverted = false;

  ILI934x(int8_t sclk, int8_t mosi, int8_t miso,
          int8_t cs, int8_t dc, int8_t rst, int8_t bl, bool inverted)
    : Adafruit_GFX(320, 240) {
    _sclk = sclk; _mosi = mosi; _miso = miso;
    _cs = cs; _dc = dc; _rst = rst; _bl = bl; _inverted = inverted;
  }

  void initPins() {
    pinMode(_sclk, OUTPUT); pinMode(_mosi, OUTPUT);
    pinMode(_cs, OUTPUT);   pinMode(_dc, OUTPUT);
    if (_rst >= 0) pinMode(_rst, OUTPUT);
    if (_miso >= 0) pinMode(_miso, INPUT);
    if (_bl >= 0)   { pinMode(_bl, OUTPUT); digitalWrite(_bl, HIGH); }
    digitalWrite(_sclk, LOW); digitalWrite(_cs, HIGH);
  }

  void spiW(uint8_t b) {                       // запись байта
    for (int i = 7; i >= 0; i--) {
      digitalWrite(_sclk, LOW);
      digitalWrite(_mosi, (b >> i) & 1);
      digitalWrite(_sclk, HIGH);
    }
    digitalWrite(_sclk, LOW);
  }

  uint8_t spiR(void) {                         // чтение байта
    uint8_t r = 0;
    digitalWrite(_mosi, HIGH);                 // dummy
    for (int i = 0; i < 8; i++) {
      digitalWrite(_sclk, LOW); digitalWrite(_sclk, HIGH);
      r = (r << 1) | (digitalRead(_miso) ? 1 : 0);
    }
    digitalWrite(_sclk, LOW);
    return r;
  }

  void cmd(uint8_t c) {
    digitalWrite(_cs, LOW); digitalWrite(_dc, LOW); spiW(c); digitalWrite(_cs, HIGH);
  }
  void data(uint8_t d) {
    digitalWrite(_cs, LOW); digitalWrite(_dc, HIGH); spiW(d); digitalWrite(_cs, HIGH);
  }
  uint8_t readCmd(uint8_t c) {
    digitalWrite(_cs, LOW); digitalWrite(_dc, LOW); spiW(c);
    digitalWrite(_dc, HIGH);
    uint8_t r = spiR();
    digitalWrite(_cs, HIGH);
    return r;
  }

  void begin() {
    initPins();
    if (_rst >= 0) { digitalWrite(_rst, HIGH); delay(5); digitalWrite(_rst, LOW); delay(20); digitalWrite(_rst, HIGH); delay(120); }
    else { cmd(SWRESET); delay(120); }
    cmd(SLPOUT); delay(100);            // выход из сна
    cmd(COLMOD); data(0x55);            // 16 бит/пиксель
    cmd(_inverted ? INVON : INVOFF);    // инверсия в зависимости от платы
    cmd(DISPON); delay(20);
    setRotation(0);
  }

  void setRotation(uint8_t r) {
    Adafruit_GFX::setRotation(r);       // width/height пересчитаются
    uint8_t mad = 0;
    switch (r) {
      case 1: mad = MADCTL_MX; break;
      case 2: mad = MADCTL_MV | MADCTL_MX | MADCTL_MY; break;
      case 3: mad = MADCTL_MY; break;
      default: mad = 0; break;
    }
    cmd(MADCTL); data(mad);
  }

  void setWindow(uint16_t x0, uint16_t y0, uint16_t x1, uint16_t y1) {
    cmd(CASET); data(x0 >> 8); data(x0); data(x1 >> 8); data(x1);
    cmd(PASET); data(y0 >> 8); data(y0); data(y1 >> 8); data(y1);
  }

  void startWrite() {
    digitalWrite(_cs, LOW);
  }
  void endWrite() {
    digitalWrite(_cs, HIGH);
  }

  void drawPixel(int16_t x, int16_t y, uint16_t c) {
    if (x < 0 || y < 0 || x >= _width || y >= _height) return;
    digitalWrite(_cs, LOW);
    setWindow(x, y, x, y);
    digitalWrite(_dc, HIGH);
    spiW(c >> 8); spiW(c & 0xFF);
    digitalWrite(_cs, HIGH);
  }

  void writeColor(uint16_t c, uint32_t n) {
    digitalWrite(_dc, HIGH);
    while (n--) { spiW(c >> 8); spiW(c & 0xFF); }
  }

  void fillScreen(uint16_t c) {
    digitalWrite(_cs, LOW);
    setWindow(0, 0, width() - 1, height() - 1);
    digitalWrite(_dc, HIGH);
    for (uint32_t i = 0; i < (uint32_t)width() * height(); i++) { spiW(c >> 8); spiW(c & 0xFF); }
    digitalWrite(_cs, HIGH);
  }

  // Чтение ID контроллера (0x04) + пикселя — проверка, что дисплей отвечает
  uint32_t readID() {
    // 3 байта ID
    uint32_t id = 0;
    digitalWrite(_cs, LOW); digitalWrite(_dc, LOW); spiW(RDID);
    digitalWrite(_dc, HIGH);
    for (int i = 0; i < 3; i++) { id = (id << 8) | spiR(); }
    digitalWrite(_cs, HIGH);
    return id;
  }
};

// ---------- Наборы пинов для перебора ----------
// { SCLK, MOSI, MISO, CS, DC, RST, BL, inverted }
const ILI934x presets[] = {
  ILI934x(18, 23, 19,  5,  2,  4, 27, false),
  ILI934x(18, 23, 19,  5,  2,  4, 27, true),
  ILI934x(14, 13, 12, 15, 33, 32, 21, false),
  ILI934x(18, 23, -1,  5,  2,  4, 27, false),
  ILI934x(18, 19, 20,  5,  2,  4, 27, false),
  ILI934x(18, 23, 19, 14, 27, 26, -1, false),
};
const int NUM = sizeof(presets) / sizeof(presets[0]);
ILI934x *disp = nullptr;   // тот, что заработал

void setup() {
  Serial.begin(115200);
  delay(700);
  Serial.println("\n=== Scout (own driver) start ===");

  for (int i = 0; i < NUM; i++) {
    Serial.printf("Try #%d\n", i);
    disp = (ILI934x*)&presets[i];
    disp->begin();
    uint32_t id = disp->readID();
    Serial.printf("   readID = 0x%06X\n", id);

    disp->fillScreen(ILI9341_WHITE);   // в Adafruit_GFX определено
    delay(1000);

    // Дисплей семейства ILI9341 отвечает ID ~0x9x / 0x93/0x94
    bool found = ( (id & 0xFF) == 0x93 || (id & 0xFF) == 0x94 ) &&
                 (id != 0x000000);
    if (found) {
      Serial.printf("\n>>> MATCH preset #%d (ID=0x%06X)\n", i, id);
      // оставляем белым
      return;
    }
    Serial.println("   (no match by ID; left off)");
  }

  // Если ID не совпал — оставляем последний набор белым и смотрим глазами
  disp = (ILI934x*)&presets[0];
  disp->begin();
  disp->fillScreen(ILI9341_WHITE);
  Serial.println("No ID match — check visually if white shows.");
  disp->fillScreen(0x0000); // чёрный
  delay(800);
  disp->fillScreen(ILI9341_WHITE);
}

void loop() { delay(5000); }

